-- Demo portfolio, part 1 of 2: the fixture rows (src/fixtures/*.json) seeded into the real tables so the deployed tool shows the demo data.
-- Sites and the three named profiles exist already (matched by code and email); the history triggers are paused so the fixture
-- history rows are the only ones; the protection triggers pass because a migration has no signed-in identity.
create temp table tmp_p (k text primary key, id uuid);
create function pg_temp.s(c text) returns uuid language sql as $$ select id from public.sites where code = c $$;
create function pg_temp.p(k text) returns uuid language sql as $$ select id from tmp_p where tmp_p.k = p.k $$;
alter table public.projects disable trigger projects_write_history;
alter table public.reference_figures disable trigger reference_figures_write_history;

-- made-up site users of the demo (no login identity; sign-ups are off, so they cannot log in)

-- reference figures

-- projects, in submission order so every predecessor exists before its resubmission
alter table public.projects enable trigger projects_write_history;
alter table public.reference_figures enable trigger reference_figures_write_history;
