insert into public.projects (id, project_code, title, category, scope, site_id, description, total_impact, annual_impact, unit, start_year, capex_eur, opex_eur_per_year, owner_name, status, version, supersedes_project_id, created_by, created_at, updated_by, updated_at) values
('16daaf55-6284-565b-83fc-aee3d92ce63e', 'PRJ-0002', 'Rooftop PV 2.4 MWp on the filling halls', 'Emissions', 'site', pg_temp.s('1000'), '2.4 MWp photovoltaic installation on the roofs of halls 3 to 5, self-consumption of about 85 %.', 11500, 1150, 'tCO₂e per year', 2025, 1900000, -180000, 'Dirk Sauer', 'Approved', 1, null, pg_temp.p('dirk'), '2025-01-20T09:15:00+00:00', pg_temp.p('zy'), '2025-04-15T14:00:00+00:00'),
('95aad904-3d98-5391-8fc9-1d06dd2e844c', 'PRJ-0026', 'Closed-loop cooling for the extruders', 'Water', 'site', pg_temp.s('1500'), 'Replace once-through cooling of the extruders with a closed loop and a dry cooler.', 49000, 9800, 'm³ per year', 2025, 520000, -9000, 'Petra Hollmann', 'Approved', 1, null, pg_temp.p('petr'), '2025-01-28T09:15:00+00:00', pg_temp.p('zy'), '2025-04-15T14:00:00+00:00'),
('72bba7f9-088b-597b-b270-54f925888ce6', 'PRJ-0001', 'Biomass boiler for process steam', 'Emissions', 'site', pg_temp.s('1000'), 'Replace the two gas-fired steam boilers with a 12 MW wood-chip boiler fed from regional forestry residues. Covers 70 % of the site''s process steam.', 31000, 6200, 'tCO₂e per year', 2026, 4800000, -320000, 'Anke Rieger', 'Approved', 1, null, pg_temp.p('anke'), '2025-02-10T09:15:00+00:00', pg_temp.p('zy'), '2025-05-20T11:00:00+00:00'),
('b2815922-4891-5446-9961-bf7b34439706', 'PRJ-0007', 'Electric forklift fleet and chargers', 'Emissions', 'site', pg_temp.s('1100'), 'Replace the 38 diesel and LPG forklifts with lithium-ion electric trucks and install 20 charging points.', 1900, 380, 'tCO₂e per year', 2025, 620000, -35000, 'Tobias Wendt', 'Approved', 1, null, pg_temp.p('tobi'), '2025-02-18T09:15:00+00:00', pg_temp.p('zy'), '2025-04-15T14:00:00+00:00'),
('78038660-bb16-52c6-9bd4-b9ceaf639ac9', 'PRJ-0022', 'Bottle-washer water recycling and CIP recovery', 'Water', 'site', pg_temp.s('1000'), 'Recover the final rinse of the bottle washers and the last CIP rinse for reuse as pre-rinse water.', 190000, 38000, 'm³ per year', 2026, 1200000, -45000, 'Anke Rieger', 'Approved', 1, null, pg_temp.p('anke'), '2025-02-24T09:15:00+00:00', pg_temp.p('zy'), '2025-04-15T14:00:00+00:00'),
('d12199f5-8d05-59f5-8262-d23bc31e822a', 'PRJ-0003', 'Heat recovery from spray dryers', 'Emissions', 'site', pg_temp.s('1300'), 'Exhaust-air heat exchangers on both spray dryers, pre-heating the inlet air and the CIP water.', 17000, 3400, 'tCO₂e per year', 2026, 2100000, -140000, 'Miriam Koch', 'Approved', 1, null, pg_temp.p('miri'), '2025-03-05T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('9688a7f5-fc44-5bd3-99ff-dc5fdc10f9e9', 'PRJ-0012', 'Boiler economisers', 'Emissions', 'site', pg_temp.s('1400'), 'Flue-gas economisers on both steam boilers, pre-heating the feed water.', 2050, 410, 'tCO₂e per year', 2025, 180000, -15000, 'Lars Brinkmann', 'Obsolete', 1, null, pg_temp.p('lars'), '2025-03-11T09:15:00+00:00', pg_temp.p('zy'), '2026-07-01T14:00:00+00:00'),
('f5159702-e430-5cf3-ad3b-0b3d10fa3849', 'PRJ-0036', 'Organic residues to the biogas plant', 'Waste', 'site', pg_temp.s('1300'), 'Divert organic production residues to the neighbouring biogas plant.', 600, 120, 'tonnes diverted per year', 2025, 55000, -6000, 'Miriam Koch', 'Approved', 1, null, pg_temp.p('miri'), '2025-03-24T09:15:00+00:00', pg_temp.p('zy'), '2025-04-15T14:00:00+00:00'),
('8ee91886-ffb8-5cb3-ad64-928ea119f3f7', 'PRJ-0005', 'Compressed air leak programme and new compressors', 'Emissions', 'site', pg_temp.s('1500'), 'Leak survey and repair, pressure reduction and two variable-speed compressors replacing the fixed-speed units.', 4100, 820, 'tCO₂e per year', 2025, 410000, -60000, 'Petra Hollmann', 'Approved', 1, null, pg_temp.p('petr'), '2025-04-01T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('964082cf-2eb5-56c7-b691-885f9cac7df4', 'PRJ-0018', 'Night setback and compressed-air zoning', 'Emissions', 'site', pg_temp.s('1200'), 'Automatic shutdown of air supply and ventilation in idle zones overnight and at weekends.', 1650, 330, 'tCO₂e per year', 2025, 95000, -22000, 'Zee', 'Approved', 1, null, pg_temp.p('zee'), '2025-04-09T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('1f373fbb-2285-502b-af1d-bcf4011b9db2', 'PRJ-0023', 'Cooling-tower blowdown reuse', 'Water', 'site', pg_temp.s('1300'), 'Treat and reuse cooling-tower blowdown as make-up for the scrubbers.', 72500, 14500, 'm³ per year', 2026, 380000, -12000, 'Miriam Koch', 'Approved', 1, null, pg_temp.p('miri'), '2025-05-05T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('fe733a2c-a577-5e87-8b31-e498ece5d1ff', 'PRJ-0008', 'LED relighting and daylight controls', 'Emissions', 'site', pg_temp.s('1600'), 'Full LED conversion of production and warehouse lighting with presence and daylight control.', 1450, 290, 'tCO₂e per year', 2025, 210000, -48000, 'Jonas Feldmann', 'Approved', 1, null, pg_temp.p('jona'), '2025-05-12T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('afdf5db9-5ceb-5dbe-9ded-0631a8cb003d', 'PRJ-0028', 'Truck-wash water recycling', 'Water', 'site', pg_temp.s('1100'), 'Recycling unit on the truck wash, 80 % water reuse.', 15500, 3100, 'm³ per year', 2026, 140000, 3000, 'Tobias Wendt', 'Approved', 1, null, pg_temp.p('tobi'), '2025-06-03T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('56475265-445d-5465-b204-c63bb57cd9be', 'PRJ-0020', 'Energy management system, ISO 50001 roll-out', 'Emissions', 'group', null, 'Sub-metering and an energy management system at all seven sites, with a group energy manager.', 6000, 1200, 'tCO₂e per year', 2026, 850000, 120000, 'Zyad Hatquai', 'Approved', 1, null, pg_temp.p('zy'), '2025-06-16T09:15:00+00:00', pg_temp.p('zy'), '2025-06-24T14:00:00+00:00'),
('f9934d4e-e6e8-5883-a980-a6785b8ad0c8', 'PRJ-0025', 'Rainwater harvesting for cooling make-up', 'Water', 'site', pg_temp.s('1200'), 'Collect roof rainwater in a 400 m³ cistern as make-up water for the cooling towers.', 31000, 6200, 'm³ per year', 2026, 290000, 4000, 'Zee', 'Approved', 1, null, pg_temp.p('zee'), '2025-07-15T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('8c9e3b9e-de0a-5630-afc3-b3a0e9a60b09', 'PRJ-0031', 'Pallet and stretch-film take-back with the recycler', 'Waste', 'site', pg_temp.s('1100'), 'Return broken pallets and stretch film to the packaging recycler instead of the mixed-waste skip.', 1000, 200, 'tonnes diverted per year', 2026, 25000, -8000, 'Tobias Wendt', 'Approved', 1, null, pg_temp.p('tobi'), '2025-08-11T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('cdcb5326-5f0e-5ef2-b7ca-54aea1193b10', 'PRJ-0010', 'Kiln insulation and burner upgrade', 'Emissions', 'site', pg_temp.s('1200'), 'Re-insulate the sugar-boiling kilns and fit modulating low-NOx burners.', 4500, 900, 'tCO₂e per year', 2026, 2300000, -20000, 'Zee', 'Declined', 1, null, pg_temp.p('zee'), '2025-08-20T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('6f71abbc-1420-5642-9300-afa33e48a46d', 'PRJ-0013', 'Solar thermal for the washing lines', 'Emissions', 'site', pg_temp.s('1500'), 'Solar thermal collectors feeding the hot-water buffer of the washing lines.', 1300, 260, 'tCO₂e per year', 2026, 540000, 5000, 'Petra Hollmann', 'Retired', 1, null, pg_temp.p('petr'), '2025-09-02T09:15:00+00:00', pg_temp.p('petr'), '2026-02-10T14:00:00+00:00'),
('68837b33-fe56-5463-84e8-da936beba028', 'PRJ-0009', 'Fleet electrification, company cars and vans', 'Emissions', 'group', null, 'Group policy: every replaced company car and service van is battery-electric from 2026; charging at all seven sites.', 3200, 640, 'tCO₂e per year', 2026, 1100000, -70000, 'Zyad Hatquai', 'Approved', 1, null, pg_temp.p('zy'), '2025-09-08T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('21232280-ee36-565a-8eca-ea485d4b71b8', 'PRJ-0032', 'Confectionery by-products to animal feed', 'Waste', 'site', pg_temp.s('1200'), 'Send sugar and starch by-products to a registered feed producer instead of incineration without recovery.', 900, 180, 'tonnes diverted per year', 2026, 40000, -15000, 'Zee', 'Approved', 1, null, pg_temp.p('zee'), '2025-09-16T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('90d454bb-acfb-5dda-a92c-81dbec313b17', 'PRJ-0017', 'Steam trap survey and pipe insulation', 'Emissions', 'site', pg_temp.s('1300'), 'Survey and replace failed steam traps; insulate 2.3 km of steam and condensate lines.', 3050, 610, 'tCO₂e per year', 2026, 150000, -30000, 'Miriam Koch', 'Approved', 1, null, pg_temp.p('miri'), '2025-10-06T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('a870b813-2b4d-588b-afa2-fe5ab8f8b9ec', 'PRJ-0035', 'Group hazardous-waste contract with recovery clause', 'Waste', 'group', null, 'One group contract for hazardous waste requiring recovery routes where they exist.', 750, 150, 'tonnes diverted per year', 2026, 0, 10000, 'Zyad Hatquai', 'Approved', 1, null, pg_temp.p('zy'), '2025-10-13T09:15:00+00:00', pg_temp.p('zy'), '2025-11-19T14:00:00+00:00'),
('ce116942-e8c4-5a7a-b2cc-83aab108f280', 'PRJ-0037', 'Glass cullet return to the supplier', 'Waste', 'site', pg_temp.s('1000'), 'Return broken glass to the bottle supplier for remelting.', 450, 90, 'tonnes diverted per year', 2026, 15000, 0, 'Anke Rieger', 'Declined', 1, null, pg_temp.p('anke'), '2025-12-02T09:15:00+00:00', pg_temp.p('zy'), '2026-03-25T14:00:00+00:00'),
('5321ac08-28c6-5ddc-a50c-b19636166b7f', 'PRJ-0010', 'Kiln insulation and burner upgrade', 'Emissions', 'site', pg_temp.s('1200'), 'Re-insulate the sugar-boiling kilns and fit modulating low-NOx burners. Revised: insulation only on the four main kilns, burners from the supplier''s standard range.', 4250, 850, 'tCO₂e per year', 2027, 1600000, -20000, 'Zee', 'Approved', 2, 'cdcb5326-5f0e-5ef2-b7ca-54aea1193b10', pg_temp.p('zee'), '2026-01-14T09:15:00+00:00', pg_temp.p('zy'), '2026-03-25T14:00:00+00:00'),
('e9261aca-0a43-50a2-962d-9face40e695b', 'PRJ-0030', 'Group leak detection and smart metering', 'Water', 'group', null, 'Smart water meters and leak detection at all seven sites, with a group dashboard.', 40000, 8000, 'm³ per year', 2026, 300000, 20000, 'Zyad Hatquai', 'Declined', 1, null, pg_temp.p('zy'), '2026-02-03T09:15:00+00:00', pg_temp.p('zy'), '2026-02-17T14:00:00+00:00'),
